        }
        self.healing_actions = AutoHealingOrchestrator()

    async def continuous_health_check(self):
        """Run continuous system health monitoring"""
        while True:
            health_status = {}

            for check_name, checker in self.health_checks.items():
                try:
                    status = await checker.check()
                    health_status[check_name] = status

                    if status.severity >= Severity.WARNING:
                        await self.healing_actions.attempt_healing(
                            check_name, status
                        )
                except Exception as e:
                    logger.error(f"Health check {check_name} failed: {e}")
                    health_status[check_name] = HealthStatus.UNKNOWN

            # Publish aggregated health metrics
            await self.publish_health_metrics(health_status)
